"""Record source-bound local edit briefs before generation."""
from pathlib import Path
import hashlib,json,shutil
V=Path(__file__).resolve().parent;L=V.parents[1];R=L.parents[2]
(V/'references').mkdir(exist_ok=True);(V/'art').mkdir(exist_ok=True)
for name in ['front_reference','washing_reference']:shutil.copy2(R/'tmp/pdfs/book_cover_v33'/f'{name}.png',V/'references'/f'{name}.png')
rp=json.loads((V/'reference_provenance.json').read_text('utf8'))
for ref in rp['references']:ref['path']=(V/'references'/Path(ref['path']).name).relative_to(R).as_posix()
(V/'reference_provenance.json').write_text(json.dumps(rp,indent=2)+'\n',encoding='utf8',newline='\n')
jobs=[dict(id='front_story_cleanup',target='references/front_reference.png',references=['references/front_reference.png','../../art/language_v26/puff_unwell.png'],prompt='Use case: precise-object-edit. IMAGE_1 is the exact front-cover edit target, with no lettering. IMAGE_2 is ONLY Grand Puff facial identity/mood reference. Make two local corrections to IMAGE_1. First remove ALL obsolete art-making debris from the lower-right foreground: the tipped pink paint pot, pink paint spill/drops, and the illustrated paper with shells/stars/rainbows. Fill those footprints with the same continuous aqua/lavender marble floor and its existing broad reflected light. Keep Baby Eagle and every toe untouched, keep the bucket/brush and Roshan’s yellow sponge. Second change ONLY the little lavender Puff face peeking through the right-hand door: replace his sharp mischievous brows and grin with a soft worried/unwell expression matching IMAGE_2. Keep his original size, location, lavender cloud body, curls, ears and door exactly fixed. Preserve every pixel outside these two correction neighborhoods as closely as possible: Roshan, Daddy, Rumi, Eagle, all anatomy/costumes, architecture, rainbow waterfall, palette, brushwork and the blank title sky remain unchanged. This is a bounded repair, not a scene redraw. Crisp polished painted2D children’s book; no text, no new props, no sticker rim, no photorealism. Return the complete1484x1060 landscape canvas.'),
dict(id='rear_hidden_lamma',target='references/washing_reference.png',references=['references/washing_reference.png','../../../../../assets/sprites/stuffie_studio/lamma.png'],prompt='Use case: precise-object-edit. IMAGE_1 is the exact existing book scene26 washing Grand Puff, the rear-cover edit target. IMAGE_2 is ONLY the canonical white Lamma identity reference. Preserve the entire scene unchanged and add ONE tiny, subtle hidden Lamma head peeking from behind an existing teapot on the small rear wall shelf just to the right of Puff’s right spiral ear and above Rumi. The peeking head is only about25-30pixels tall on the1484x1060 target; most of Lamma is occluded by the existing shelf object. Retain her round white woolly face, small sideways ears, dark lash eyes, tiny peach nose and blush; no visible egg. She is a very easy-to-miss background discovery, not a fifth helper. Keep all characters, anatomy, identities, washing gestures/contact, sponges/brushes, bubbles, room geometry, fixtures, colors and painted2D style EXACTLY fixed. Change only this tiny shelf neighborhood; do not add dust bunnies, drawings, craft paper, paint spill, new furniture or lettering. No full-scene redraw. Return the complete1484x1060 landscape canvas.')]
for j in jobs:
 refs=[]
 for i,s in enumerate(j['references'],1):
  p=(V/s).resolve();assert p.is_file(),str(p)
  refs.append(dict(role='edit_target' if i==1 else 'identity_reference',path=p.relative_to(R).as_posix(),sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
 j['references']=refs;j['prompt_sha256']=hashlib.sha256(j['prompt'].encode()).hexdigest();j['generation_method']='built-in image_gen';j['attempt']=1
(V/'generation_jobs.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
print('Two local edit briefs and durable reference images saved.')
